def slug(n):
    return 'm_' + re.sub(r'[^A-Za-z0-9]+', '_', n).strip('_')


def main():
    out = []
    for n, es, lv, eq, cat, force, m, s, i, ies, k, kes in X:
        assert len(i) == len(ies) and len(k) == len(kes), n
        out.append({'id': slug(n), 'n': n, 'l': lv, 'e': eq, 'c': cat, 'm': m, 's': s, 'f': force, 'i': i, 'x': True,
                    'k': k, 'es': {'n': es, 'i': ies, 'k': kes}, 'src': 'FitQuest (original text)'})
    assert len(out) == 40, len(out)
    OUT.write_text(json.dumps(out, ensure_ascii=False, separators=(',', ':')))
    print('wrote', OUT, len(out), 'exercises')


if __name__ == '__main__':
    main()
